from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [v for v in {x for row in grid for x in row} if v != bg]
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    dirs8 = tuple((dr, dc) for dr in (-1, 0, 1)
                  for dc in (-1, 0, 1) if dr or dc)

    def components(color, dirs):
        seen = [[False] * w for _ in range(h)]
        comps = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or seen[r][c]:
                    continue
                seen[r][c] = True
                q = [(r, c)]
                cells = []
                for rr, cc in q:
                    cells.append((rr, cc))
                    for dr, dc in dirs:
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and
                                not seen[nr][nc] and grid[nr][nc] == color):
                            seen[nr][nc] = True
                            q.append((nr, nc))
                comps.append(cells)
        return comps

    def square_side(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        height = max(rs) - min(rs) + 1
        width = max(cs) - min(cs) + 1
        if height == width and height >= 2 and len(cells) == height * width:
            return height
        return None

    comps4 = {color: components(color, dirs4) for color in colors}
    endpoint_candidates = []
    for color in colors:
        comps = comps4[color]
        sides = [square_side(comp) for comp in comps]
        if (len(comps) == 2 and all(side is not None for side in sides)
                and sides[0] == sides[1]):
            endpoint_candidates.append(color)

    if endpoint_candidates:
        end_color = endpoint_candidates[0]
    else:
        # Fallback: choose the color with exactly two repeated solid squares.
        end_color = colors[0]
        best = -1
        for color in colors:
            sides = [square_side(comp) for comp in comps4[color]]
            valid = [side for side in sides if side is not None]
            if len(valid) == 2 and valid[0] == valid[1]:
                end_color = color
                break
            if len(valid) > best:
                best = len(valid)
                end_color = color

    remaining = [color for color in colors if color != end_color]
    if len(remaining) < 2:
        return out

    # The intermediate objects are the other color with the most solid square
    # components; the remaining color is the thin connecting trace.
    def square_count(color):
        return sum(square_side(comp) is not None for comp in comps4[color])

    mid_color = max(remaining, key=square_count)
    line_color = next(color for color in remaining if color != mid_color)

    nodes = []
    kinds = []
    for comp in comps4[end_color]:
        nodes.append(comp)
        kinds.append("end")
    for comp in comps4[mid_color]:
        nodes.append(comp)
        kinds.append("mid")
    for comp in components(line_color, dirs8):
        nodes.append(comp)
        kinds.append("line")

    if len([i for i, kind in enumerate(kinds) if kind == "end"]) != 2:
        return out

    node_at = [[-1] * w for _ in range(h)]
    for i, cells in enumerate(nodes):
        for r, c in cells:
            node_at[r][c] = i

    adj = [set() for _ in nodes]
    for i, cells in enumerate(nodes):
        for r, c in cells:
            for dr, dc in dirs8:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    j = node_at[nr][nc]
                    if j >= 0 and j != i:
                        adj[i].add(j)

    ends = [i for i, kind in enumerate(kinds) if kind == "end"]
    start, goal = ends
    prev = {start: None}
    q = deque([start])
    while q and goal not in prev:
        i = q.popleft()
        for j in adj[i]:
            if j not in prev:
                prev[j] = i
                q.append(j)

    if goal not in prev:
        return out

    path = []
    cur = goal
    while cur is not None:
        path.append(cur)
        cur = prev[cur]

    for i in path:
        if kinds[i] == "mid":
            for r, c in nodes[i]:
                out[r][c] = 3
        elif kinds[i] == "line":
            for r, c in nodes[i]:
                out[r][c] = 5

    return out

