def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = []
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            cells = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if (0 <= q[0] < h and 0 <= q[1] < w
                            and q not in seen and grid[q[0]][q[1]] == color):
                        seen.add(q)
                        stack.append(q)
