                       for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    adjacent.append(i)
            if not adjacent:
                best = 999
                nearest = []
                for i, comp in enumerate(comps):
                    d = min(abs(r - y) + abs(c - x)
                            for y, x in comp["cells"])
                    if d < best:
                        best, nearest = d, [i]
                    elif d == best:
                        nearest.append(i)
                if best <= 2:
                    adjacent = nearest
            if adjacent:
                for i in adjacent:
                    comps[i]["ports"].add((r, c))
