def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    objects = []

    for r in range(h - 4):
        for c in range(w - 4):
            border = grid[r][c]
            if border == bg:
                continue
            fill = grid[r + 1][c + 1]
            if fill == bg or fill == border:
                continue

            valid = True
            for dr in range(5):
                for dc in range(5):
                    expected = border if dr in (0, 4) or dc in (0, 4) else fill
                    if grid[r + dr][c + dc] != expected:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                objects.append((r, c, border, fill))

    final_cols = {}
    for border in {obj[2] for obj in objects}:
        indices = [i for i, obj in enumerate(objects) if obj[2] == border]
        placed = []

        if border == 8:
            indices.sort(key=lambda i: (objects[i][1], objects[i][0]))
            for i in indices:
                r, c, _, _ = objects[i]
                new_c = 0
                for pr, pc in placed:
                    if max(r, pr) < min(r + 5, pr + 5):
                        new_c = max(new_c, pc + 5)
                final_cols[i] = new_c
                placed.append((r, new_c))
        else:
            indices.sort(key=lambda i: (-objects[i][1], objects[i][0]))
            for i in indices:
                r, c, _, _ = objects[i]
                new_c = w - 5
                for pr, pc in placed:
                    if max(r, pr) < min(r + 5, pr + 5):
                        new_c = min(new_c, pc - 5)
                final_cols[i] = new_c
                placed.append((r, new_c))

    out = [[bg for _ in range(w)] for _ in range(h)]
    for i, (r, _, border, fill) in enumerate(objects):
        c = final_cols[i]
        for dr in range(5):
            for dc in range(5):
                out[r + dr][c + dc] = (
                    border if dr in (0, 4) or dc in (0, 4) else fill
                )
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    wall = None
    for c in range(w):
        values = {grid[r][c] for r in range(h)}
        if len(values) == 1 and next(iter(values)) != 0:
            wall = c
            break

    if wall is None:
        return out

    for r in range(h):
        left = grid[r][:wall]
        if not any(left):
            continue

        # A different color immediately before the divider spreads across
        # the empty area on the other side.
        if wall >= 2 and left[-1] != 0 and left[-2] != 0 and left[-2] != left[-1]:
            for c in range(wall + 1, w):
                out[r][c] = left[-1]
            continue

        # Otherwise, repeat the longest contiguous color run at its width.
        runs = []
        c = 0
        while c < wall:
            if left[c] == 0:
                c += 1
                continue
            color = left[c]
            end = c + 1
            while end < wall and left[end] == color:
                end += 1
            runs.append((end - c, color))
            c = end

        length, color = max(runs)
        for c in range(wall + 1, w):
            if (c - wall - 1) % length == 0:
                out[r][c] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    n = next(c for c, value in enumerate(grid[0]) if value == 5)
    starts = range(0, w - n + 1, n + 1)

    # Each top panel defines a sprite and its output color.
    sprites = {}
    marker_row = 2 * n + 3
    for start in starts:
        cells = [
            grid[r][start + c]
            for r in range(n)
            for c in range(n)
            if grid[r][start + c] not in (0, 5)
        ]
        if not cells:
            continue

        color = max(set(cells), key=cells.count)
        mask = [
            (r, c)
            for r in range(n)
            for c in range(n)
            if grid[r][start + c] == color
        ]
        target = grid[marker_row][start + n // 2]
        sprites[color] = (target, mask)

    out = [[0] * (n * n) for _ in range(n * n)]

    # The middle panels encode where each sprite should appear.
    for start in starts:
        for r in range(n):
            for c in range(n):
                color = grid[n + 1 + r][start + c]
                if color not in sprites:
                    continue

                target, mask = sprites[color]
                for dr, dc in mask:
                    out[r * n + dr][c * n + dc] = target

    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not zeros:
        return [row[:] for row in grid]

    sr = min(r for r, c in zeros)
    sc = min(c for r, c in zeros)
    nr = max(r for r, c in zeros) - sr + 1
    nc = max(c for r, c in zeros) - sc + 1
    start = (sr, sc)

    valid = set()
    for r in range(h - nr + 1):
        for c in range(w - nc + 1):
            if all(grid[i][j] != 3
                   for i in range(r, r + nr)
                   for j in range(c, c + nc)):
                valid.add((r, c))

    valid.add(start)
    dist = {start: 0}
    queue = deque([start])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nxt = (r + dr, c + dc)
            if nxt in valid and nxt not in dist:
                dist[nxt] = dist[(r, c)] + 1
                queue.append(nxt)

    goal = None
    if twos:
        goal = (min(r for r, c in twos), min(c for r, c in twos))

    if goal in dist:
        dest = goal
    else:
        endpoints = []
        for r, c in dist:
            degree = sum((r + dr, c + dc) in dist for dr, dc in directions)
            if degree <= 1:
                endpoints.append((r, c))
        candidates = endpoints or list(dist)
        dest = max(candidates, key=lambda p: dist[p])

    out = [row[:] for row in grid]
    for r, c in zeros:
        out[r][c] = 1
    for r in range(dest[0], dest[0] + nr):
        for c in range(dest[1], dest[1] + nc):
            out[r][c] = 0
    return out

def transform(grid):
    H, W = len(grid), len(grid[0])

    def tile(th, tw, target, pieces):
        coords = sorted(target)
        if sum(len(p) for p in pieces) != len(coords):
            return None
        index = {p: i for i, p in enumerate(coords)}
        by_cell = [[] for _ in coords]

        for pi, piece in enumerate(pieces):
            mr = min(r for r, c, v in piece)
            mc = min(c for r, c, v in piece)
            shape = [(r - mr, c - mc, v) for r, c, v in piece]
            ph = max(r for r, c, v in shape) + 1
            pw = max(c for r, c, v in shape) + 1
            if ph > th or pw > tw:
                return None

            for top in range(th - ph + 1):
                for left in range(tw - pw + 1):
                    vals = []
                    cover = 0
                    valid = True
                    for dr, dc, color in shape:
                        q = index.get((top + dr, left + dc))
                        if q is None:
                            valid = False
                            break
                        cover |= 1 << q
                        vals.append((q, color))
                    if valid:
                        pl = (pi, 1 << pi, cover, tuple(vals))
                        for q, color in vals:
                            by_cell[q].append(pl)

        if any(not by_cell[i] for i in range(len(coords))):
            return None

        failed = set()

        def search(uncovered, remaining):
            if not uncovered:
                return [] if not remaining else None
            state = (uncovered, remaining)
            if state in failed:
                return None

            best = None
            bits = uncovered
            while bits:
                low = bits & -bits
                q = low.bit_length() - 1
                opts = []
                for pl in by_cell[q]:
                    if (remaining & pl[1]) and (pl[2] & uncovered) == pl[2]:
                        opts.append(pl)
                if not opts:
                    failed.add(state)
                    return None
                if best is None or len(opts) < len(best):
                    best = opts
                    if len(best) == 1:
                        break
                bits ^= low

            for pl in best:
                tail = search(uncovered ^ pl[2], remaining ^ pl[1])
                if tail is not None:
                    return [pl] + tail
            failed.add(state)
            return None

        placements = search((1 << len(coords)) - 1, (1 << len(pieces)) - 1)
        if placements is None:
            return None

        out = [[0] * tw for _ in range(th)]
        # The caller supplies the background separately.
        for pl in placements:
            for q, color in pl[3]:
                r, c = coords[q]
                out[r][c] = color
        return out

    candidates = []
    seen = set()

    def add_candidate(tb, sb):
        tr0, tr1, tc0, tc1 = tb
        sr0, sr1, sc0, sc1 = sb
        th, tw = tr1 - tr0, tc1 - tc0
        if th <= 0 or tw <= 0 or sr1 <= sr0 or sc1 <= sc0:
            return

        palette = set()
        target = set()
        for r in range(tr0, tr1):
            for c in range(tc0, tc1):
                v = grid[r][c]
                palette.add(v)
                if len(palette) > 2:
                    return
        if len(palette) != 2:
            return

        source_values = [
            grid[r][c]
            for r in range(sr0, sr1)
            for c in range(sc0, sc1)
        ]
        if not source_values:
            return
        freq = {}
        for v in source_values:
            freq[v] = freq.get(v, 0) + 1
        most = max(freq.values())

        for bg in palette:
            if freq.get(bg, 0) != most or 2 * most < len(source_values):
                continue

            for r in range(tr0, tr1):
                for c in range(tc0, tc1):
                    if grid[r][c] == bg:
                        target.add((r - tr0, c - tc0))

            if not target or len(target) != len(source_values) - freq[bg]:
                target.clear()
                continue

            key = (tb, sb, bg)
            if key in seen:
                target.clear()
                continue
            seen.add(key)

            cells = {}
            for r in range(sr0, sr1):
                for c in range(sc0, sc1):
                    if grid[r][c] != bg:
                        cells[(r, c)] = grid[r][c]

            unseen = set(cells)
            pieces = []
            while unseen:
                start = min(unseen)
                unseen.remove(start)
                stack = [start]
                comp = []
                while stack:
                    r, c = stack.pop()
                    comp.append((r, c, cells[(r, c)]))
                    for nr, nc in ((r - 1, c), (r + 1, c),
                                   (r, c - 1), (r, c + 1)):
                        if (nr, nc) in unseen:
                            unseen.remove((nr, nc))
                            stack.append((nr, nc))
                pieces.append(comp)

            candidates.append((th * tw, th, tw, bg, target, pieces))
            target.clear()

    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)):
            add_candidate((0, r, 0, W), (r + 1, H, 0, W))
            add_candidate((0, r + 1, 0, W), (r + 1, H, 0, W))
            add_candidate((r + 1, H, 0, W), (0, r, 0, W))
            add_candidate((r, H, 0, W), (0, r, 0, W))

    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)):
            add_candidate((0, H, 0, c), (0, H, c + 1, W))
            add_candidate((0, H, 0, c + 1), (0, H, c + 1, W))
            add_candidate((0, H, c + 1, W), (0, H, 0, c))
            add_candidate((0, H, c, W), (0, H, 0, c))

    candidates.sort(key=lambda x: -x[0])
    for area, th, tw, bg, target, pieces in candidates:
        result = tile(th, tw, target, pieces)
        if result is not None:
            for r in range(th):
                for c in range(tw):
                    if (r, c) not in target:
                        result[r][c] = bg
            return result

    return [row[:] for row in grid]

def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    occupied = {
        (r, c): grid[r][c]
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg
    }

    directions = [(0, 1), (1, 0), (1, -1), (1, 1)]
    dr, dc = max(
        directions,
        key=lambda d: sum(
            (r + d[0], c + d[1]) in occupied
            for r, c in occupied
        ),
    )

    if (dr, dc) == (0, 1):       # horizontal
        mode = "h"
    elif (dr, dc) == (1, 0):     # vertical
        mode = "v"
    elif (dr, dc) == (1, -1):    # down-left diagonal
        mode = "dl"
    else:                        # down-right diagonal
        mode = "dr"

    def line_and_position(r, c):
        if mode == "h":
            return r, c
        if mode == "v":
            return c, r
        if mode == "dl":
            return r + c, r
        return r - c, r

    def coordinate(key, t):
        if mode == "h":
            return key, t
        if mode == "v":
            return t, key
        if mode == "dl":
            return t, key - t
        return t, t - key

    groups = defaultdict(list)
    for (r, c), color in occupied.items():
        key, t = line_and_position(r, c)
        groups[key].append((t, color))

    segments = []
    for key, points in groups.items():
        points.sort()
        run = []

        def save_run():
            if run:
                segments.append({
                    "key": key,
                    "lo": run[0][0],
                    "hi": run[-1][0],
                    "color": run[0][1],
                })

        for t, color in points:
            if run and (t != run[-1][0] + 1 or color != run[-1][1]):
                save_run()
                run = []
            run.append((t, color))
        save_run()

    if not segments:
        return [row[:] for row in grid]

    segments.sort(key=lambda s: (s["key"], s["lo"]))
    middle = segments[len(segments) // 2]
    target_length = middle["hi"] - middle["lo"] + 1

    def perpendicular_position(key, t):
        if mode in ("h", "v"):
            return t
        return 2 * t - key

    lo_positions = [perpendicular_position(s["key"], s["lo"]) for s in segments]
    hi_positions = [perpendicular_position(s["key"], s["hi"]) for s in segments]
    lo_spread = max(lo_positions) - min(lo_positions)
    hi_spread = max(hi_positions) - min(hi_positions)
    keep_lo = lo_spread <= hi_spread

    out = [row[:] for row in grid]

    # Clear the original segments before drawing their resized versions.
    for s in segments:
        for t in range(s["lo"], s["hi"] + 1):
            r, c = coordinate(s["key"], t)
            out[r][c] = bg

    for s in segments:
        if keep_lo:
            first = s["lo"]
        else:
            first = s["hi"] - target_length + 1

        for t in range(first, first + target_length):
            r, c = coordinate(s["key"], t)
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = s["color"]

    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    owner = [[-1] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or owner[r][c] != -1:
                continue
            idx = len(components)
            color = grid[r][c]
            cells = []
            owner[r][c] = idx
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            owner[ny][nx] == -1 and grid[ny][nx] == color):
                        owner[ny][nx] = idx
                        q.append((ny, nx))
            components.append((color, cells))

    adj = [set() for _ in components]
    for r in range(h):
        for c in range(w):
            a = owner[r][c]
            if a < 0:
                continue
            for nr, nc in ((r + 1, c), (r, c + 1)):
                if nr < h and nc < w:
                    b = owner[nr][nc]
                    if b >= 0 and a != b:
                        adj[a].add(b)
                        adj[b].add(a)

    endpoints = [i for i in range(len(components)) if len(adj[i]) <= 1]
    start = min(endpoints or range(len(components)),
                key=lambda i: min(components[i][1]))

    order = []
    seen = set()

    def walk(i):
        if i in seen:
            return
        seen.add(i)
        order.append(i)
        for j in sorted(adj[i], key=lambda k: min(components[k][1])):
            walk(j)

    walk(start)
    for i in sorted(range(len(components)), key=lambda k: min(components[k][1])):
        walk(i)

    return [[components[i][0]] for i in order
            for _ in range(len(components[i][1]))]

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    marker = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                marker = (r, c)
                break
        if marker is not None:
            break

    seen = set()
    bars = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (1, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] in (1, 2)
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            rows = [rr for rr, _ in cells]
            cols = [cc for _, cc in cells]
            if min(rows) == max(rows):
                bars.append({
                    "orientation": "H",
                    "pos": rows[0],
                    "lo": min(cols),
                    "hi": max(cols),
                    "ones": sum(grid[rr][cc] == 1 for rr, cc in cells),
                })
            elif min(cols) == max(cols):
                bars.append({
                    "orientation": "V",
                    "pos": cols[0],
                    "lo": min(rows),
                    "hi": max(rows),
                    "ones": sum(grid[rr][cc] == 1 for rr, cc in cells),
                })

    for r in range(h):
        for c in range(w):
            if out[r][c] == 1:
                out[r][c] = 2

    if marker is None or not bars:
        return out

    orientation = bars[0]["orientation"]
    bars = [b for b in bars if b["orientation"] == orientation]
    mr, mc = marker

    if orientation == "V":
        p, q = mc, mr
        main_size, lateral_size = w, h
        direction = 1 if p <= (main_size - 1) // 2 else -1
    else:
        p, q = mr, mc
        main_size, lateral_size = h, w
        direction = 1 if p <= (main_size - 1) // 2 else -1

    bars.sort(key=lambda b: direction * b["pos"])

    def point(main, lateral):
        if orientation == "V":
            return (lateral, main)
        return (main, lateral)

    def draw(a, b):
        r1, c1 = a
        r2, c2 = b
        if r1 == r2:
            for cc in range(min(c1, c2), max(c1, c2) + 1):
                if 0 <= r1 < h and 0 <= cc < w:
                    out[r1][cc] = 3
        else:
            for rr in range(min(r1, r2), max(r1, r2) + 1):
                if 0 <= rr < h and 0 <= c1 < w:
                    out[rr][c1] = 3

    for bar in bars:
        margin = bar["ones"] + 1
        turn = bar["pos"] - direction * margin

        draw(point(p, q), point(turn, q))

        low = bar["lo"] - margin
        high = bar["hi"] + margin
        choices = [x for x in (low, high) if 0 <= x < lateral_size]
        if choices:
            target = min(choices, key=lambda x: abs(x - q))
        else:
            target = max(0, min(lateral_size - 1, low))

        draw(point(turn, q), point(turn, target))
        p, q = turn, target

    end = main_size - 1 if direction > 0 else 0
    draw(point(p, q), point(end, q))
    return out

