    out = [row[:] for row in grid]
    base = grid[1][1]

    def panel(start_col):
        return [
            [grid[r + 1][start_col + c] for c in range(5)]
            for r in range(5)
        ]

    a = panel(1)
    b = panel(7)
    c = panel(13)
    marked = {
        (r, col)
        for r in range(5)
        for col in range(5)
        if a[r][col] != base
    }

