    # remaining marked cell indicates the side for panel B.
    components = []
    unseen = set(marked)
    while unseen:
        start = unseen.pop()
        component = {start}
        stack = [start]
        while stack:
            r, col = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, col + dc)
                    if (dr or dc) and p in unseen:
                        unseen.remove(p)
                        component.add(p)
                        stack.append(p)
        components.append(component)

    divider = max(components, key=len)
    markers = marked - divider
    marker = next(iter(markers))

    # Find which side of the divider contains the marker, using
    # four-way movement so diagonal dividers also separate the regions.
    marker_region = {marker}
    stack = [marker]
    while stack:
        r, col = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, col + dc)
            if (0 <= p[0] < 5 and 0 <= p[1] < 5
                    and p not in divider and p not in marker_region):
