        for col in range(5):
            if (r, col) in divider:
                # Both patterns meet on the divider; panel B has priority.
                value = b[r][col] if b[r][col] != base else c[r][col]
            elif (r, col) in marker_region:
                value = b[r][col]
            else:
                value = c[r][col]
            out[r + 1][19 + col] = value

