def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    points = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                points.setdefault(color, []).append((r, c))

    def aligned(p, q):
        dr = abs(p[0] - q[0])
        dc = abs(p[1] - q[1])
        return dr == 0 or dc == 0 or dr == dc

    def segment(p, q):
        dr = q[0] - p[0]
        dc = q[1] - p[1]
        steps = max(abs(dr), abs(dc))
        sr = (dr > 0) - (dr < 0)
        sc = (dc > 0) - (dc < 0)
        return [(p[0] + i * sr, p[1] + i * sc)
                for i in range(steps + 1)]

    paths = {}
    for color, ps in points.items():
        edges = set()
        for p in ps:
            candidates = []
            for q in ps:
                if q != p and aligned(p, q):
                    dr = p[0] - q[0]
                    dc = p[1] - q[1]
                    candidates.append((dr * dr + dc * dc, q))
            candidates.sort()
            if candidates:
                cutoff = candidates[min(1, len(candidates) - 1)][0]
                for distance, q in candidates:
                    if distance <= cutoff:
                        edges.add(tuple(sorted((p, q))))

        cells = set()
        for p, q in edges:
            cells.update(segment(p, q))
        paths[color] = cells

    copies = []
    for target, target_points in points.items():
        if len(target_points) != 1:
            continue
        q = target_points[0]
        for source, source_points in points.items():
            if source == target or len(source_points) < 2:
                continue
            for p in source_points:
                dr = q[0] - p[0]
                dc = q[1] - p[1]
                if max(abs(dr), abs(dc)) == 1:
                    for r, c in paths[source]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            copies.append((target, nr, nc))

    out = [row[:] for row in grid]
    for color, r, c in copies:
        if grid[r][c] == 0:
            out[r][c] = color

    for color, cells in paths.items():
        for r, c in cells:
            if grid[r][c] == 0:
                out[r][c] = color

    return out

def transform(grid):
    import math

    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []

    # The nonzero connected components are the pieces.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x, grid[y][x]))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < len(grid[ny])
                            and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            min_r = min(y for y, x, v in cells)
            min_c = min(x for y, x, v in cells)
            pieces.append([(y - min_r, x - min_c, v)
                           for y, x, v in cells])

    total = sum(len(p) for p in pieces)
    if total == 0:
        return []
    side = math.isqrt(total)
    if side * side != total:
        return [row[:] for row in grid]

    marker_piece = next(
        (i for i, p in enumerate(pieces) if any(v == 5 for r, c, v in p)),
        None
    )

    def orientations(base, allow_reflection):
        seeds = [base]
        if allow_reflection:
            width = max(c for r, c, v in base) + 1
            seeds.append([(r, width - 1 - c, v) for r, c, v in base])

        result = []
        seen_shapes = set()
        for seed in seeds:
            cur = seed
            for _ in range(4):
                key = tuple(sorted(cur))
                if key not in seen_shapes:
                    seen_shapes.add(key)
                    result.append(key)
                height = max(r for r, c, v in cur) + 1
                cur = [(c, height - 1 - r, v) for r, c, v in cur]
        return result

    def pack(allow_reflection, anchor_marker):
        placements = []
        by_cell = []

        for piece in pieces:
            piece_places = []
            for shape in orientations(piece, allow_reflection):
                ph = max(r for r, c, v in shape) + 1
                pw = max(c for r, c, v in shape) + 1
                if ph > side or pw > side:
                    continue
                for top in range(side - ph + 1):
                    for left in range(side - pw + 1):
                        mask = 0
                        entries = []
                        for r, c, v in shape:
                            idx = (top + r) * side + left + c
                            mask |= 1 << idx
                            entries.append((idx, v))
                        piece_places.append((mask, tuple(entries)))
            placements.append(piece_places)

            cell_lists = [[] for _ in range(side * side)]
            for place in piece_places:
                bits = place[0]
                while bits:
                    bit = bits & -bits
                    cell_lists[bit.bit_length() - 1].append(place)
                    bits -= bit
            by_cell.append(cell_lists)

        full = (1 << (side * side)) - 1
        all_used = (1 << len(pieces)) - 1

        def search(occupied, used, chosen):
            if used == all_used:
                return chosen if occupied == full else None

            free = full ^ occupied
            if not free:
                return None
            idx = (free & -free).bit_length() - 1

            for p in range(len(pieces)):
                if used & (1 << p):
                    continue
                for place in by_cell[p][idx]:
                    if place[0] & occupied:
                        continue
                    answer = search(
                        occupied | place[0],
                        used | (1 << p),
                        chosen + [(p, place)]
                    )
                    if answer is not None:
                        return answer
            return None

        if anchor_marker and marker_piece is not None:
            for place in placements[marker_piece]:
                if any(idx == 0 and value == 5 for idx, value in place[1]):
                    answer = search(
                        place[0],
                        1 << marker_piece,
                        [(marker_piece, place)]
                    )
                    if answer is not None:
                        return answer
            return None

        return search(0, 0, [])

    solution = pack(False, True)
    if solution is None:
        solution = pack(True, True)
    if solution is None:
        solution = pack(False, False)
    if solution is None:
        solution = pack(True, False)
    if solution is None:
        return [[0] * side for _ in range(side)]

    out = [[0] * side for _ in range(side)]
    for piece_id, place in solution:
        for idx, value in place[1]:
            out[idx // side][idx % side] = value
    return out

def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = max(counts, key=counts.get)

    # Find the vertical two-column color key near the lower-left.
    runs = []
    for c in range(w - 1):
        r = 0
        while r < h:
            if grid[r][c] == background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != background:
                r += 1
            end = r - 1
            length = end - start + 1
            if length >= 2 and start >= h // 2:
                right_count = sum(
                    grid[rr][c + 1] != background
                    for rr in range(start, end + 1)
                )
                runs.append((length, right_count, -c, start, c, end))

    mappings = []
    key_cells = set()
    if runs:
        _, _, _, start, key_col, end = max(runs)
        for r in range(start, end + 1):
            mappings.append((grid[r][key_col], grid[r][key_col + 1]))
            key_cells.add((r, key_col))
            key_cells.add((r, key_col + 1))

    # Find same-colored 4-connected components outside the key.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or (r, c) in key_cells:
                continue
            color = grid[r][c]
            if color == background:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                rr, cc = stack.pop()
                cells.add((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (
                        0 <= nr < h and 0 <= nc < w
                        and (nr, nc) not in seen
                        and (nr, nc) not in key_cells
                        and grid[nr][nc] == color
                    ):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append((color, cells))

    by_color = {}
    for color, cells in components:
        by_color.setdefault(color, []).append(cells)

    def l_info(cells):
        if len(cells) != 3:
            return None
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 != 1 or c1 - c0 != 1:
            return None
        missing = next(
            (r, c)
            for r in (r0, r1)
            for c in (c0, c1)
            if (r, c) not in cells
        )
        orientation = (missing[0] - r0, missing[1] - c0)
        return r0, r1, c0, c1, orientation

    fills = []
    restore_cells = set()
    square_recolors = []

    for source, target in mappings:
        l_shapes = []
        for cells in by_color.get(source, []):
            info = l_info(cells)
            if info is not None:
                l_shapes.append((cells, info))

        pair_options = []
        for i in range(len(l_shapes)):
            for j in range(i + 1, len(l_shapes)):
                cells_a, info_a = l_shapes[i]
                cells_b, info_b = l_shapes[j]
                oa, ob = info_a[4], info_b[4]
                if oa[0] == ob[0] or oa[1] == ob[1]:
                    continue

                points = cells_a | cells_b
                r0 = min(r for r, c in points)
                r1 = max(r for r, c in points)
                c0 = min(c for r, c in points)
                c1 = max(c for r, c in points)
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                pair_options.append(
                    (area, r0, r1, c0, c1, points)
                )

        if pair_options:
            area, r0, r1, c0, c1, markers = max(
                pair_options, key=lambda item: item[0]
            )
            if target != 0:
                fills.append((area, target, r0, r1, c0, c1))
            if target != 0 or target == background:
                restore_cells.update(markers)

        # A solid 2x2 object acts as a color-replacement sample.
        if target != 0:
            for cells in by_color.get(source, []):
                if len(cells) == 4:
                    r0 = min(r for r, c in cells)
                    r1 = max(r for r, c in cells)
                    c0 = min(c for r, c in cells)
                    c1 = max(c for r, c in cells)
                    if r1 - r0 == 1 and c1 - c0 == 1:
                        square_recolors.append((cells, target))

    out = [row[:] for row in grid]

    # Larger rectangles are laid down first so smaller ones can overlay them.
    fills.sort(key=lambda item: item[0], reverse=True)
    for area, color, r0, r1, c0, c1 in fills:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color

    for cells, color in square_recolors:
        for r, c in cells:
            out[r][c] = color

    for r, c in restore_cells:
        out[r][c] = grid[r][c]

    return out

