    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)

    def in_panel(r, c):
        return r0 <= r <= r1 and c0 <= c <= c1

    # Count connected same-color objects outside the panel.
    seen = set()
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if in_panel(r, c) or color in (0, bg) or (r, c) in seen:
                continue
            counts[color] = counts.get(color, 0) + 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                cr, cc = stack.pop()
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            not in_panel(nr, nc) and
                            grid[nr][nc] == color and
                            (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color == 0:
                continue
            row, col = r - r0, c - c0
            for k in range(counts.get(color, 1)):
                target_col = col + 2 * k
                if target_col < len(out[0]):
                    out[row][target_col] = color
    return out

def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])

    # Find connected components of color 1.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if src[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            src[nr][nc] == 1 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(cells)

    def get_cell(g, t, k, orientation):
        return g[t][k] if orientation == "v" else g[k][t]

    def set_cell(g, t, k, orientation, value):
        if orientation == "v":
            g[t][k] = value
        else:
            g[k][t] = value

    for cells in components:
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)

        # Each side is (orientation, first layer, step, cross-section range).
        sides = [
            ("v", rmin - 1, -1, cmin, cmax),
            ("v", rmax + 1,  1, cmin, cmax),
            ("h", cmin - 1, -1, rmin, rmax),
            ("h", cmax + 1,  1, rmin, rmax),
        ]

        for orientation, start, step, lo, hi in sides:
            limit = h if orientation == "v" else w
            if not (0 <= start < limit):
                continue

            # Colored cells beside the object define the ray's cross-section.
            groups = []
            current = []
            for k in range(lo, hi + 1):
                value = get_cell(src, start, k, orientation)
                if value not in (1, 8):
                    current.append(k)
                elif current:
                    groups.append(current)
                    current = []
            if current:
                groups.append(current)

            for cross in groups:
                seq = []
                t = start
                blank_at = None

                # Collect the existing contiguous colored section.
                while 0 <= t < limit:
                    vec = tuple(get_cell(src, t, k, orientation) for k in cross)
                    if all(value == 8 for value in vec):
                        blank_at = t
                        break
                    if any(value == 1 for value in vec):
                        break
                    seq.append(vec)
                    t += step

                if blank_at is None or not seq:
                    continue

                # Find the smallest repeating period of the colored section.
                period = len(seq)
                for p in range(1, len(seq) + 1):
                    if all(seq[i] == seq[i % p] for i in range(len(seq))):
                        period = p
                        break

                # Continue the pattern outward, crossing other colors if needed.
                t = blank_at
                distance = len(seq)
                while 0 <= t < limit:
                    if any(get_cell(out, t, k, orientation) == 1 for k in cross):
                        break
                    vec = seq[distance % period]
                    for k, value in zip(cross, vec):
                        set_cell(out, t, k, orientation, value)
                    t += step
                    distance += 1

    return out

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    def line_values(is_row, index):
        if is_row:
            return grid[index][:]
        return [grid[r][index] for r in range(h)]

    def repeated_line_count(is_row):
        count = 0
        number_of_lines = h if is_row else w
        for index in range(number_of_lines):
            frequencies = {}
            for value in line_values(is_row, index):
                if value != 0:
                    frequencies[value] = frequencies.get(value, 0) + 1
            if any(n >= 2 for n in frequencies.values()):
                count += 1
        return count

    use_rows = repeated_line_count(True) > repeated_line_count(False)
    number_of_lines = h if use_rows else w
    line_length = w if use_rows else h

    for index in range(number_of_lines):
        values = line_values(use_rows, index)
        positions_by_color = {}
        for pos, value in enumerate(values):
            if value != 0:
                positions_by_color.setdefault(value, []).append(pos)

        pair = None
        for color, positions in positions_by_color.items():
            for a, b in zip(positions, positions[1:]):
                gap = b - a
                if pair is None or gap < pair[0]:
                    pair = (gap, color, a, b)

        if pair is None:
            continue

        step, base_color, left, right = pair
        filled = {left, right}
        marker_color = None

        for direction, current in ((-1, left), (1, right)):
            while True:
                nxt = current + direction * step
                if nxt < 0 or nxt >= line_length:
                    break

                filled.add(nxt)
                value = values[nxt]
                if value != 0 and value != base_color:
                    if marker_color is None:
                        marker_color = value
                    break
                current = nxt

        result_color = marker_color if marker_color is not None else base_color
        for pos in filled:
            if use_rows:
                out[index][pos] = result_color
            else:
                out[pos][index] = result_color

    return out

